 Node.js (TypeScript/JS) – alap chat
ts
// pnpm add openai  vagy  npm i openai  vagy  yarn add openai
import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.XAI_API_KEY,
  baseURL: "https://api.x.ai/v1",
  // Opcionális megbízhatósági beállítások:
  maxRetries: 3,        // automatikus újrapróbálkozások
  timeout: 30_000,      // 30s socket timeout
});

async function main() {
  const resp = await client.chat.completions.create({
    model: "grok-4-fast-reasoning", // vagy: "grok-4-fast"
    temperature: 0.3,
    messages: [
      { role: "system", content: "Te egy hasznos, tömör asszisztens vagy." },
      { role: "user", content: "Foglalod össze 3 pontban a Grok 4 Fast fő előnyeit?" },
    ],
  });

  console.log(resp.choices?.[0]?.message?.content ?? "");
}

main().catch(console.error);


 Node.js – streaming tokenenként
ts
import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.XAI_API_KEY,
  baseURL: "https://api.x.ai/v1",
  maxRetries: 3,
  timeout: 30_000,
});

async function streamDemo() {
  const stream = await client.chat.completions.create({
    model: "grok-4-fast-reasoning",
    messages: [
      { role: "system", content: "Te egy hasznos, tömör asszisztens vagy." },
      { role: "user", content: "Írj egy rövid, 3 mondatos összefoglalót a modellről." },
    ],
    stream: true,
  });

  for await (const chunk of stream) {
    const delta = chunk.choices?.[0]?.delta?.content;
    if (delta) process.stdout.write(delta);
  }
  process.stdout.write("\n");
}

streamDemo().catch(console.error);


 Node.js – tool/function calling minta
ts
import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.XAI_API_KEY,
  baseURL: "https://api.x.ai/v1",
});

type WeatherArgs = { location: string; unit?: "c" | "f" };
function get_weather(args: WeatherArgs) {
  // Itt valós API‑hívást végezhetnél; most makett:
  const { location, unit = "c" } = args;
  return { location, unit, temp: unit === "f" ? 72 : 22, condition: "sunny" };
}

async function runWithTools() {
  const tools = [
    {
      type: "function",
      function: {
        name: "get_weather",
        description: "Időjárás lekérése egy helyszínhez.",
        parameters: {
          type: "object",
          properties: {
            location: { type: "string" },
            unit: { type: "string", enum: ["c", "f"] },
          },
          required: ["location"],
          additionalProperties: false,
        },
      },
    },
  ];

  const messages: OpenAI.Chat.Completions.ChatCompletionMessageParam[] = [
    { role: "system", content: "Segíts az időjárás megválaszolásában a funkcióval." },
    { role: "user", content: "Milyen az idő Budapesten Celsiusban?" },
  ];

  // 1) Első kör: a modell kérhet tool‑hívást
  const first = await client.chat.completions.create({
    model: "grok-4-fast-reasoning",
    messages,
    tools,
    tool_choice: "auto",
  });

  const msg = first.choices?.[0]?.message;
  if (msg?.tool_calls?.length) {
    for (const call of msg.tool_calls) {
      if (call.type === "function" && call.function?.name === "get_weather") {
        const args = JSON.parse(call.function.arguments || "{}") as WeatherArgs;
        const toolResult = get_weather(args);

        messages.push(msg); // a modell üzenete tool_calls-szal
        messages.push({
          role: "tool",
          tool_call_id: call.id,
          content: JSON.stringify(toolResult),
        });
      }
    }

    // 2) Második kör: végső válasz a tool output alapján
    const second = await client.chat.completions.create({
      model: "grok-4-fast-reasoning",
      messages,
    });

    console.log(second.choices?.[0]?.message?.content ?? "");
  } else {
    console.log(msg?.content ?? "");
  }
}

runWithTools().catch(console.error);


