 Python – tool/function calling
python
import os, json
from openai import OpenAI

client = OpenAI(api_key=os.environ.get("XAI_API_KEY"), base_url="https://api.x.ai/v1")

def get_weather(location: str, unit: str = "c"):
    return {"location": location, "unit": unit, "temp": 22 if unit == "c" else 72, "condition": "sunny"}

tools = [{
    "type": "function",
    "function": {
        "name": "get_weather",
        "description": "Időjárás lekérése.",
        "parameters": {
            "type": "object",
            "properties": {
                "location": {"type": "string"},
                "unit": {"type": "string", "enum": ["c", "f"]},
            },
            "required": ["location"],
            "additionalProperties": False,
        },
    },
}]

messages = [
    {"role": "system", "content": "Segíts az időjárás megválaszolásában a funkcióval."},
    {"role": "user", "content": "Milyen az idő Debrecenben Fahrenheitben?"},
]

first = client.chat.completions.create(
    model="grok-4-fast-reasoning",
    messages=messages,
    tools=tools,
    tool_choice="auto",
)

msg = first.choices[0].message
if getattr(msg, "tool_calls", None):
    for call in msg.tool_calls:
        if call.type == "function" and call.function.name == "get_weather":
            args = json.loads(call.function.arguments or "{}")
            result = get_weather(**args)
            messages.append(msg)
            messages.append({
                "role": "tool",
                "tool_call_id": call.id,
                "content": json.dumps(result),
            })

    second = client.chat.completions.create(
        model="grok-4-fast-reasoning",
        messages=messages,
    )
    print(second.choices[0].message.content)
else:
    print(msg.content)


